import React, { useEffect, useState } from 'react';
import Chart from 'chart.js/auto';
import api from '../utils/api';

const ChartComponent = () => {
    const [data, setData] = useState(null);
    const [error, setError] = useState(null);
    const [month, setMonth] = useState('');
    const [year, setYear] = useState('');

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                setData(result.data);
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    useEffect(() => {
        if (!data) return;

        const { invoices = [], loggedFlights = [] } = data;

        const filteredInvoices = invoices.filter(invoice => invoice.Status === 'Invoiced');
        const revenuePerHour = {};

        filteredInvoices.forEach(invoice => {
            const trip = invoice.Trip;
            const aircraft = invoice.Aircraft;
            const price = parseFloat(invoice.Price);
            const date = new Date(invoice['Trip Start Z']);
            
            if (month && date.getMonth() + 1 !== parseInt(month)) {
                return;
            }
            
            if (year && date.getFullYear() !== parseInt(year)) {
                return;
            }

            const flights = loggedFlights.filter(flight => flight.Trip === trip && flight.Aircraft === aircraft);
            const totalFlightHours = flights.reduce((sum, flight) => sum + parseFloat(flight['Flight hrs']), 0);

            if (!revenuePerHour[aircraft]) {
                revenuePerHour[aircraft] = { totalPrice: 0, totalFlightHours: 0 };
            }

            revenuePerHour[aircraft].totalPrice += price;
            revenuePerHour[aircraft].totalFlightHours += totalFlightHours;
        });

        const labels = Object.keys(revenuePerHour);
        const dataPoints = labels.map(aircraft => (revenuePerHour[aircraft].totalPrice / revenuePerHour[aircraft].totalFlightHours).toFixed(2));

        const ctx = document.getElementById('myChart').getContext('2d');
        new Chart(ctx, {
            type: 'bar',
            data: {
                labels,
                datasets: [{
                    label: 'Revenue per Hour',
                    data: dataPoints,
                    backgroundColor: 'rgba(75, 192, 192, 0.2)',
                    borderColor: 'rgba(75, 192, 192, 1)',
                    borderWidth: 1
                }]
            },
            options: {
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

    }, [data, month, year]);

    const handleMonthChange = (event) => {
        setMonth(event.target.value);
    };

    const handleYearChange = (event) => {
        setYear(event.target.value);
    };

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div>
            <h1>Revenue per Hour of Aircrafts</h1>
            <label>
                Select Month:
                <select value={month} onChange={handleMonthChange}>
                    <option value="">All</option>
                    <option value="1">January</option>
                    <option value="2">February</option>
                    <option value="3">March</option>
                    <option value="4">April</option>
                    <option value="5">May</option>
                    <option value="6">June</option>
                    <option value="7">July</option>
                    <option value="8">August</option>
                    <option value="9">September</option>
                    <option value="10">October</option>
                    <option value="11">November</option>
                    <option value="12">December</option>
                </select>
            </label>
            <label>
                Select Year:
                <input type="number" value={year} onChange={handleYearChange} placeholder="YYYY" />
            </label>
            <canvas id="myChart" width="400" height="400"></canvas>
        </div>
    );
};

export default ChartComponent;
